const languageKey = "efbi-site-language";
const originalTextByNode = new WeakMap();
const language = localStorage.getItem(languageKey) === "en" ? "en" : "fr";
const originalTitle = document.title;

function normalizeText(value) {
	return value.replace(/\s+/g, " ").trim().replace(/(\S)(\*{1,3})$/, "$1 $2");
}

function preserveWhitespace(originalText, translatedText) {
	const leadingWhitespace = originalText.match(/^\s*/)?.[0] ?? "";
	const trailingWhitespace = originalText.match(/\s*$/)?.[0] ?? "";
	return `${leadingWhitespace}${translatedText}${trailingWhitespace}`;
}

function getTranslation(textNode, key) {
	const item = textNode.parentElement?.closest("li");
	const itemText = item ? normalizeText(item.textContent) : "";

	if (itemText.startsWith("Le Respect")) {
		if (key === "Le") return "";
		if (key === "Respect") return "respect";
	}
	if (itemText.startsWith("Le Traitement")) {
		if (key === "Le") return "Fast, efficient";
		if (key === "Traitement") return "order processing";
	}
	if (itemText.startsWith("Le Sens")) {
		if (key === "Le") return "A strong";
		if (key === "Sens") return "sense of attentiveness";
	}
	if (itemText.startsWith("Des Prestations")) {
		if (key === "Des") return "Tailored";
		if (key === "Prestations") return "services";
	}

	return normalizedTranslations[key];
}

const normalizedTranslations = Object.fromEntries(
	Object.entries(translations).map(([source, translation]) => [normalizeText(source), translation])
);

function translatePage(selectedLanguage) {
	document.documentElement.lang = selectedLanguage;
	document.title =
		selectedLanguage === "en"
			? normalizedTranslations[normalizeText(originalTitle)] || originalTitle
			: originalTitle;
	const textWalker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
	let textNode;
	while ((textNode = textWalker.nextNode())) {
		if (textNode.parentElement?.closest("script, style, textarea")) {
			continue;
		}
		if (!originalTextByNode.has(textNode)) {
			originalTextByNode.set(textNode, textNode.nodeValue);
		}
		const originalText = originalTextByNode.get(textNode);
		const key = normalizeText(originalText);
		const translation = getTranslation(textNode, key);
		if (selectedLanguage === "en" && translation !== undefined) {
			textNode.nodeValue = preserveWhitespace(originalText, translation);
		} else if (selectedLanguage === "fr") {
			textNode.nodeValue = originalText;
		}
	}

	for (const element of document.querySelectorAll('[value]')) {
		const originalValue = element.dataset.originalValue || element.value;
		element.dataset.originalValue = originalValue;
		element.value =
			selectedLanguage === "en"
				? normalizedTranslations[normalizeText(originalValue)] || originalValue
				: originalValue;
	}

	for (const element of document.querySelectorAll("[placeholder]")) {
		const originalPlaceholder = element.dataset.originalPlaceholder || element.placeholder;
		element.dataset.originalPlaceholder = originalPlaceholder;
		element.placeholder =
			selectedLanguage === "en"
				? normalizedTranslations[normalizeText(originalPlaceholder)] || originalPlaceholder
				: originalPlaceholder;
	}

	for (const element of document.querySelectorAll("[alt]")) {
		const originalAlt = element.dataset.originalAlt || element.alt;
		element.dataset.originalAlt = originalAlt;
		element.alt =
			selectedLanguage === "en"
				? normalizedTranslations[normalizeText(originalAlt)] || originalAlt
				: originalAlt;
	}

	for (const meta of document.querySelectorAll('meta[name="description"]')) {
		const originalDescription = meta.dataset.originalDescription || meta.content;
		meta.dataset.originalDescription = originalDescription;
		meta.content =
			selectedLanguage === "en"
				? normalizedTranslations[normalizeText(originalDescription)] || originalDescription
				: originalDescription;
	}

	const switcher = document.querySelector("#site-language");
	if (switcher && switcher.value !== selectedLanguage) {
		switcher.value = selectedLanguage;
	}
}

const headerActions = document.querySelector(".left-side");
if (headerActions) {
	const languageControl = document.createElement("div");
	languageControl.className = "language-control";

	const languageSelect = document.createElement("select");
	languageSelect.id = "site-language";
	languageSelect.setAttribute("aria-label", "Eng / Fr");
	languageSelect.innerHTML = '<option value="fr">Fr</option><option value="en">Eng</option>';
	languageSelect.value = language;
	languageSelect.addEventListener("change", () => {
		localStorage.setItem(languageKey, languageSelect.value);
		translatePage(languageSelect.value);
	});

	languageControl.append(languageSelect);
	headerActions.append(languageControl);
}

translatePage(language);
